effect.script:
function animate(env,el,p) {
    let groups = [];
    groups.push(0);
    el.shaderGroups = groups;
    return el;
}

effect.shader:
    //////////////////////////
    vec4 newLayer( vec4 a, vec4 b) {
    return a * (1. - b.a) + b;
    }

    mat2 rot2m(float a){

	float s = sin(a);
	float c = cos(a);

	return mat2(c, -s, s, c);
    }

    vec2 l2s( vec2 v ) {
        return (vec4(v,0.,1.)*acLayerToScreen).xy;
    }

   #define fragCoord gl_FragCoord.xy

   /////////////////////////

        #define s(a,b,c) smoothstep(a,b,c)
        #define S(a, b, t) smoothstep(a, b, t)

        highp float rand(vec2 co) {
            return fract(cos(mod(dot(co.xy+0.12,vec2(12.9898,78.233)),3.14))*43758.5453);
        }
        highp vec3 rand3(vec2 co){
        	float t=rand(co);
        	float z=rand(co+t);
        	return vec3(t,z,rand(co+z));
        }
        vec3 getpoint(vec2 id){
                float EVO = autop? PROGRESS+(acTime*1.5) : PROGRESS;
        	vec3 r=rand3(id);
        	vec3 ou=vec3(
        		sin(EVO*r.x),
        		cos(EVO*r.y),
        		sin(EVO*r.z*10.)
        	);
        	return ou*0.45+0.5;
        }

        float line(vec2 uv, vec2 p, vec2 p2){
        	vec2 n=uv-p;
        	vec2 w=p2-p;
        	float r=clamp(dot(n,w)/dot(w,w),0.,1.);
        	r=length(n-w*r);
               return clamp(s(0.04,0.01,r)*(s(0.6,1.,1./distance(p,p2))),0.,1.);
        }

        //////////////////////////

        float N21(vec2 p)
        {
            p = fract(p*vec2(651.34, 237.73));
            p += dot(p, p + 23.45);
            return fract(p.x*p.y);
        }

        vec2 N22(vec2 p)
        {
            float n = N21(p);
            return vec2(n, N21(p+n));
        }

        vec2 GetGridPoint(vec2 id, vec2 offs)
        {
            float EVOX = autop? PROGRESS+(acTime*1.5) : PROGRESS;
            vec2 n = N22(id + offs) * EVOX;

            return offs + sin(n) * .3;
        }

        float DistToLine(vec2 p, vec2 a, vec2 b)
        {
            vec2 pa = p-a;
            vec2 ba = b-a;
            float t = clamp(dot(pa, ba)/dot(ba,ba),0.,1.);
            return length(pa - ba*t);
        }

        float LineX(vec2 p, vec2 a, vec2 b)
        {
            float d = DistToLine(p, a, b);
            float m = S(.05, .005, d);
            m *= S(1.1,.6,length(a - b));
            return m;
        }
    //////////////////////////
        void main() {
        if( acPass == 0 ) { gl_FragColor = texture2DCv(inputImg.texture, acScreenNorm.st); } else if( acPass==1 ) {
        vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
        vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

        vec2 image_size = getTexSize(inputImg.size);
        vec2 iRes = vec2(acScreenSize.x, acScreenSize.y);

        vec2 TanRyu;
        TanRyu = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
        TanRyu.y*=acLayerSize.y/acLayerSize.x;

        TanRyu /= scale;
        float angle = autor? anglex+(acTime*10.0) : anglex;
        TanRyu *= rot2m((0.0+angle)*0.0174533);
        TanRyu += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;

        vec2 scaleVec;
        scaleVec = vec2(scale*stretch.x,scale*stretch.y);
        TanRyu /= scaleVec;

        /////////////////////////

    	vec4 sparkx;

            vec2 uv = TanRyu;

            if(new) {
            vec2 id=floor(uv);
            vec2 c=fract(uv);

            vec2 p[9];
        	float col=0.;
            int i=0;
            for(float n=-1.;n<=1.;n++){
                for(float w=-1.;w<=1.;w++){
        			vec2 nc=id+vec2(w,n);
        			vec3 point=getpoint(nc);
        			p[i]=point.xy+vec2(w,n);
        			vec2 a=(p[i].xy-c)*10.;
        			col+=pow(point.z/dot(a,a),2.2);
                    i++;
        		}
        	}

            for(int i=0;i<9;i++){
        		col+=pow(line(c,p[i].xy,p[4].xy),2.2);
        	}
        	col+=pow(line(c,p[1].xy,p[3].xy),2.2);
        	col+=pow(line(c,p[1].xy,p[5].xy),2.2);
        	col+=pow(line(c,p[7].xy,p[3].xy),2.2);
            col+=pow(line(c,p[7].xy,p[5].xy),2.2);

            col=pow(col,1./2.2);
            col*=col;
            col*=0.5;

            vec3 xnxx = vec3(col);
            xnxx *= color1.rgb;

            sparkx = vec4(xnxx,1.0); }

            //////////////////////////

            // vec2 uv = TanRyu;
            else {
            vec2 index = floor(uv);
        	vec2 gridUv = fract(uv) - .5;

            vec2 px[9];

            int i = 0;
            for(float y =-1. ;y <=1. ; y++)
            {
                for(float x =-1. ;x <=1. ; x++)
                {
                    px[i++] = GetGridPoint(index, vec2(x,y));
                }
            }

            float result = 0.;
            for(int i=0; i< 9; i++)
            {
                result += LineX(gridUv, px[4], px[i]);

            }
            result += LineX(gridUv, px[1], px[3]);
            result += LineX(gridUv, px[1], px[5]);
            result += LineX(gridUv, px[3], px[7]);
            result += LineX(gridUv, px[5], px[7]);    

            vec3 colx = vec3(result);
            colx *= color1.rgb;

            sparkx = vec4(colx,1.0); }

    	vec4 factor = mix(texColorX,sparkx,1.0);
    	// vec4 factor = mix(texColorX,fragColor,1.0);

        vec4 resultfinal;
        if( blendMode==0 ) {                // normal
            resultfinal = (factor * bright) * texColor.a;
            // resultfinal = (newLayer(texColor, factor) * bright) * texColor.a;
        } else if( blendMode==1 ) {         // multiply
            factor *= bright;
            vec4 c = factor + vec4(1.)*(1.-factor.a);
            resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a;
        } else if( blendMode==2 ) {         // screen
            factor *= bright;
            resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a;
        }

    	gl_FragColor = mix(texColor, resultfinal, alpha);
          }
        }
